      { type: "response.output_text.delta", item_id: "msg_1", output_index: 0, delta: text },
      {
        type: "response.output_item.done",
        output_index: 0,
        item: {
          type: "message",
          id: "msg_1",
          content: [{ type: "output_text", text, annotations: [] }],
        },
      },
    );
